IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
; A cave that scrolls a pixel a frame, with 21 patterns: the pairs of tiles side
; by side in its 11 rows of rock, rewritten every frame at the new shift
; straight after HALT; the names change every eighth frame: written into the
; table not shown in the loop that turns R#2, and shown by the next turn,
; eight frames later (chapter 29).
; A ship, a sprite, flies the sky between, as the demo's keys say.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $02          ; Graphic II
        VDP_REG 2, $06          ; names    $1800
        VDP_REG 3, $9F          ; colours  $2000, one set for three thirds
        VDP_REG 4, $00          ; shapes   $0000, one set for three thirds
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $01          ; the border
