        out (VDP_DATA), a
        ld hl, VARS             ; the variables' page, all 0
        ld de, VARS + 1
        ld bc, 255
        ld (hl), 0
        ldir
        ld a, 1
        ld (dleft), a           ; the demo's first pair at the first frame
        ld hl, demo
        ld (dnext), hl
        ld hl, first            ; the sprite's attributes at the start
        ld de, copy
        ld bc, 5
        ldir
        VRAM_WRITE $0000        ; pattern 0, the sky
        ld c, VDP_DATA
        xor a
        ld b, 8
.sky:   out (c), a
        djnz .sky
        ld hl, shifts           ; and the pairs at shift 0
        ld b, NB
        otir
        VRAM_WRITE $2000        ; the sky's colours, and the pairs'
        ld b, 8
        ld a, $41
.skyc:  out (c), a
        djnz .skyc
        ld hl, pcols
        ld b, NB
        otir
        VRAM_WRITE $1800        ; both name tables all sky
        call sky
        VRAM_WRITE $1C00
        call sky
        ld a, $1C
        ld (table), a
        xor a
        call window             ; window 0 in the table at $1800
        ld a, $18
        ld (table), a
        ld a, 1
        call window             ; window 1 in the table at $1C00, not shown
        ld a, 1
        ld (shift), a           ; the first frame: a pixel on
        VRAM_WRITE SPAT         ; the ship's patterns
        ld hl, sprite
        ld bc, 32 << 8 | VDP_DATA
        otir
        jp on

; sky: 768 names of the sky, 0, to the VRAM, with the display off
sky:    ld de, 768
.name:  xor a
        out (VDP_DATA), a
        dec de
        ld a, d
        or e
        jr nz, .name
        ret
on:     ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        in a, (VDP_CTRL)        ; no signal left over
        VDP_REG 1, $E2          ; display on, the frame's signal
