frame:  halt                    ; isr: the status kept, the frame counted
woke:   call sends              ; 18  what the beam must not catch
sent:   call run                ; 18  the frame's work
ran:    jr frame                ; 13

; isr: every frame. The status kept in stat, the signal let down; the frame
; counted. Keeps AF, HL
isr:    push af                 ; 12
