        ld hl, copy             ; 11
        ld bc, 5 << 8 | VDP_DATA ; 11  the ship and the end
        otir                    ; 23 a byte, 18 the last
show:   VRAM_WRITE $0008        ; 40  pair 1's pattern, the first
        ld a, (shift)           ; 14
