        add a, low stab         ;  8
        ld l, a                 ;  5
        ld h, high stab         ;  8  HL: the shift's place in stab
        ld a, (hl)              ;  8
        inc l                   ;  5
        ld h, (hl)              ;  8
        ld l, a                 ;  5  HL: the pairs at this shift
        ld b, NB                ;  8
        otir                    ; 23 a byte, 18 the last
        ld a, (shift)           ; 14
        or a                    ;  5
        ret nz                  ; 12, or 6  seven frames in eight, no more
        ld a, (table)           ; 14
        xor $18 ^ $1C           ;  8  the other table: the next window
        ld (table), a           ; 14
