        rrca                    ;  5  $06 or $07, R#2's
        out (VDP_CTRL), a       ; 12
        ld a, $80 | 2           ;  8
        out (VDP_CTRL), a       ; 12
        ret                     ; 11

; run: the frame's work: the demo's keys, the ship steered, the scroll.
;      Uses every register
